"use client";

/** Trigger a browser download for generated bytes or text. */
export function downloadBlob(data: Uint8Array | string, filename: string, type: string) {
  const blob = data instanceof Uint8Array ? new Blob([data as BlobPart], { type }) : new Blob([data], { type });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function slugify(s: string) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "child";
}
